// Récupérer la date depuis le Trigger Notion (formulaire de création de bail)
const triggerData = $('Notion Trigger - Nouveau formulaire').item.json;
const dateObj = triggerData['Date de début de location'];
const dateDebutStr = dateObj?.start;

// Vérifier que la date existe
if (!dateDebutStr) {
  throw new Error(`Date de début non trouvée dans le trigger. Propriétés : ${JSON.stringify(Object.keys(triggerData))}`);
}

const dateDebut = new Date(dateDebutStr);

// Vérifier que la date est valide
if (isNaN(dateDebut.getTime())) {
  throw new Error(`Date invalide : ${dateDebutStr}`);
}

const mois = dateDebut.getMonth() + 1;
const annee = dateDebut.getFullYear();

let trimestre;
if (mois >= 1 && mois <= 3) trimestre = `T4 ${annee - 1}`;
else if (mois >= 4 && mois <= 6) trimestre = `T1 ${annee}`;
else if (mois >= 7 && mois <= 9) trimestre = `T2 ${annee}`;
else trimestre = `T3 ${annee}`;

// Calcul date de renouvellement (1 an après date début)
const dateRenouvellement = new Date(dateDebut);
dateRenouvellement.setFullYear(dateRenouvellement.getFullYear() + 1);

const jour = dateRenouvellement.getDate().toString().padStart(2, '0');
const moisNom = ['janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août', 'septembre', 'octobre', 'novembre', 'décembre'][dateRenouvellement.getMonth()];
const anneeRenouv = dateRenouvellement.getFullYear();
const dateRevision = `${jour} ${moisNom} ${anneeRenouv}`;

// Calcul date du jour pour la signature
const aujourdhui = new Date();
const jourAujourdhui = aujourdhui.getDate().toString().padStart(2, '0');
const moisAujourdhui = ['janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août', 'septembre', 'octobre', 'novembre', 'décembre'][aujourdhui.getMonth()];
const anneeAujourdhui = aujourdhui.getFullYear();
const dateSignature = `${jourAujourdhui} ${moisAujourdhui} ${anneeAujourdhui}`;

// Calcul loyer total
const montantLoyer = parseFloat(triggerData['Montant du loyer hors-charge'] || 0);
const montantCharges = parseFloat(triggerData['Montant des charges'] || 0);
const montantLoyerTotal = montantLoyer + montantCharges;

// Calcul premier versement (caution + loyer prorata)
const jourDebut = dateDebut.getDate();
const caution = montantLoyer; // 1 mois HC
let loyerPremierMois;
let detailPremierVersement;

if (jourDebut <= 15) {
  loyerPremierMois = montantLoyerTotal;
  detailPremierVersement = `${caution}€ de caution + ${loyerPremierMois}€ de loyer (mois complet)`;
} else {
  loyerPremierMois = montantLoyerTotal / 2;
  detailPremierVersement = `${caution}€ de caution + ${loyerPremierMois}€ de loyer (demi-mois)`;
}

const montantPremierVersement = caution + loyerPremierMois;

return {
  json: {
    ...$json,
    reference_irl: trimestre,
    date_revision: dateRevision,
    date_signature: dateSignature,
    montant_loyer: montantLoyer,
    montant_charges: montantCharges,
    montant_loyer_total: montantLoyerTotal,
    depot_garantie: caution,
    montant_premier_versement: montantPremierVersement,
    detail_premier_versement: detailPremierVersement
  }
};

